from PIL import Image
import math
u=Image.open('/home/robot/captures/side_012.jpg');l=Image.open('/home/robot/captures/side_020.jpg')
for xs in [(296,304),(335,344),(300,340)]:
 pu=[sum(u.getpixel((x,y))[0] for x in range(*xs))/(xs[1]-xs[0]) for y in range(480)]
 pl=[sum(l.getpixel((x,y))[0] for x in range(*xs))/(xs[1]-xs[0]) for y in range(480)]
 v=pl[203:249]; vm=sum(v)/len(v);v=[t-vm for t in v];vn=sum(t*t for t in v)
 def obj(a,d):
  yy=[190+(y-190-d)/a for y in range(203,249)]
  q=[pu[int(y)]*(1-y%1)+pu[int(y)+1]*(y%1) for y in yy];qm=sum(q)/len(q);q=[t-qm for t in q]
  return sum(t*w for t,w in zip(v,q))/math.sqrt(vn*sum(t*t for t in q))
 best=(-1,0,0)
 for ai in range(850,1031,2):
  for di in range(500,1101,4):
   a=ai/1000;d=di/100; r=obj(a,d)
   if r>best[0]:best=(r,a,d)
 print(xs,best,flush=True)
 print('unload',[(y,round(pu[y],1)) for y in range(190,253)])
 print('load',[(y,round(pl[y],1)) for y in range(200,253)])
PY
